use vstd::prelude::*;

verus! {
    fn findMax(a: &[i32], n: usize) -> (max_index: usize)
        requires
            n > 0,
            a.len() >= n,
        ensures
            max_index < n,
            a[max_index] == a[0..n].iter().cloned().max().unwrap(),
    {
        let mut max_index = 0;
        let mut max_value = a[0];

        // Loop invariant to maintain the properties during the iteration
        for i in 1..n
            invariant
                0 < i <= n,
                max_index < i,
                max_value == a[0..i].iter().cloned().max().unwrap(),
        {
            if a[i] > max_value {
                max_value = a[i];
                max_index = i;
            }
        }

        max_index
    }
}

